-- 2. 会議カード: 9/15 社内定例（Geminiの議事メモから。報告書の打合せ記録に載せた回）
INSERT INTO project_meeting_summaries (meeting_id, project_id, ym, meeting_date, meeting_start_at, title, notion_url, calendar_event_id,
  summary_short, decided, progress, next_actions, risks, source_hash, generated_at, generated_by_model, notion_page_id, source_kinds, source_url, narrative_md)
VALUES ($m$3db3u7cmq5gif30afqlegdd9ju_20260914T020000Z$m$, 'p20', '202609', DATE '2026-09-15', TIMESTAMPTZ '2026-09-15 08:00:00+00', $m$【確定】CX Internal MTG$m$, NULL, $m$3db3u7cmq5gif30afqlegdd9ju_20260914T020000Z$m$,
  $m$契約最終月の納品物の計画を確認し、財務・事業計画の最終成果物の作成、コスト試算、デューデリジェンスの準備を分担した。創業の時期と、早く会社を作る利点（営業・資金の話ができる）と負担（研究開発の時間が減る）を整理し、こーじさんが判断できるように伝えることで一致した。創業の時期の結論は持ち越し。$m$, $m$["コスト試算の結果は、成果物としてPDFで出す。", "メンバー限定の共有ワークスペースを、会社の設立前からメンバー向けに使えるようにする。", "視野を広げるため、経営者への接触やイベントへの参加を意識して増やす。"]$m$::jsonb, $m$["あきが、財務を最優先として資料のスプレッドシート化とアジェンダの整理を進めている。", "まさが、ユニットエコノミクスと条件ごとの設備投資・運営費を比べられるコスト試算の仕組みを作っており、黒字になる領域とならない領域が見え始めた。", "資金調達を含むキャッシュフローと資本政策を入れた事業計画（あき作成）は、こーじさんが納得できるよう9月末の納品に向けてまさが詰める。", "NIMSに所属したまま兼業すると、発明した知財はNIMSの所有になる。クロスアポイントメントなら共同出願の余地はあるが、神谷さんが関わる以上NIMSを外した単独出願は想定しにくい（りり）。", "会社を今作る一番の利点は営業と資金の話ができること、負担は研究開発の時間が減ることと整理した（りり）。"]$m$::jsonb, $m$["業務工程のステップ4・5の計画書を作る（まさ）。", "財務・事業計画の最終成果物をPDFで作る（まさ）。", "提出物の中身をこーじさんに確認してもらう（まさ）。", "ユニットエコノミクス・市場データ・競合情報を集め、取りこぼしている技術情報をまさへ送る（あき）。", "会社設立の利点と負担を整理し、判断材料を用意する（あき）。", "こーじさんとの1on1を予約する（まさ）。"]$m$::jsonb, $m$["創業の時期の結論が出ていない。", "ADRの100mKでの安定稼働や熱スイッチの切り替えなど、製品として残る技術課題がある。", "NIMSの研究者の時間をスタートアップの製品開発にそのまま使えない。会社の成果とNIMSの成果を最初から切り分ける必要がある。"]$m$::jsonb,
  'manual-amie-2026-10-03:p20:20260915', NOW(), 'manual-amie-2026-10-03', NULL, $m$drive$m$, $m$https://docs.google.com/document/d/1oAxCr65yx4iFCBsKfbSxjY8axNNTGpD8u1w1ZZ6Kvic/edit$m$, $m$## 🎯背景
2026年9月15日の17:00から、CXの社内定例。NIMSとの受託契約の最終月で、9月末の納品物を仕上げる段階。出席はまさ・あき・りり。

## 📊経緯
あきから、前回に続いて財務を最優先とし、スプレッドシート化とアジェンダの整理を進めていると報告があった。まさは、今月の納品物がすべて終わるかの確認に加え、投資家に見せられる形に仕上げたいと述べ、任意の項目（ステップ4・5）は計画書として自分で作ると示した。ピッチ資料については、初期の接点は取れても投資に至っていないという肌感覚があり、まさは、技術成熟度にこだわらず、研究機関向けに確実に作って売れるならVCから直ちに調達できなくても会社を作る意味はあると述べた。まさは、市場規模の裏付けとユニットエコノミクスのコスト試算を進めており、条件ごとに設備投資と運営費を比べると黒字になる領域とならない領域が見えてきたと説明した。成果物の形式は、PDF・スプレッドシートに加え、メンバー限定の共有ワークスペースを使い、ゴールツリーなどを段階的に移す。後半は創業の時期を議論した。りりは、NIMSに所属したまま兼業すると発明した知財はNIMSの所有になり、クロスアポイントメントなら共同出願の余地があるが、神谷さんが関わる以上NIMSを外した単独出願は想定しにくいと説明した。会社を今作る利点は営業と資金の話ができること、負担は研究開発の時間が減ることと整理し、こーじさんがこの交換条件を分かったうえで判断できるよう伝えることで一致した。

## ✅決まったこと
- コスト試算の結果は、成果物としてPDFで出す。
- メンバー限定の共有ワークスペースを、会社の設立前からメンバー向けに使えるようにする。
- 視野を広げるため、経営者への接触やイベントへの参加を意識して増やす。

## ▶️次の一手
- 業務工程のステップ4・5の計画書を作る（まさ）。
- 財務・事業計画の最終成果物をPDFで作り、こーじさんに中身を確認してもらう（まさ）。
- ユニットエコノミクス・市場データ・競合情報を集め、取りこぼしている技術情報をまさへ送る（あき）。
- 会社設立の利点と負担を整理し、判断材料を用意する（あき）。
- こーじさんとの1on1を予約する（まさ）。

## ⚠️残課題
- 創業の時期の結論は持ち越し。
- ADRの100mKでの安定稼働や熱スイッチの切り替えなど、製品として残る技術課題がある。
- NIMSの研究者の時間をスタートアップの製品開発にそのまま使えない。会社の成果とNIMSの成果を最初から切り分ける必要がある。$m$)
