ON CONFLICT (project_id, ym) DO UPDATE SET revenue_yen = EXCLUDED.revenue_yen, cogs_yen = EXCLUDED.cogs_yen, personnel_yen = EXCLUDED.personnel_yen,
  rd_yen = EXCLUDED.rd_yen, marketing_yen = EXCLUDED.marketing_yen, other_opex_yen = EXCLUDED.other_opex_yen, notes = EXCLUDED.notes, updated_at = NOW();
DO $$ BEGIN
  IF (SELECT count(*) FROM project_pl_monthly WHERE project_id = 'p20' AND ym BETWEEN '2027-01' AND '2036-12' AND notes LIKE '見込: 成果物3%') <> 120 THEN RAISE EXCEPTION 'pl rows mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM project_pl_monthly WHERE project_id = 'p20' AND notes LIKE 'NewCo base plan%') THEN RAISE EXCEPTION 'old base plan rows remain'; END IF;
END $$;

