SELECT '8fbcce69-5ee8-5e35-860a-e011a92f6cd6', 'p20', '202609', DATE '2026-09-30', 'funding', $m$資本政策を、設立時の親族出資（株式1億円＋転換社債4億円）中心に組み直した$m$, $m$まさ確定。設立直後に親族から株式1億円（調達前の評価額5億円）と転換社債4億円を受ける。転換社債は、試作機の性能・再現性の確認（2027年6月の計画）で2億円を転換前の評価額10億円で、初号機の有償納品・顧客検収（2028年1月の計画）で残り2億円を同20億円で株式に替える。転換するまでは返済に備えて保管する。VCからの調達は基本計画に入れず、上場時（2035年、公募20億円・調達前の評価額200億円は仮置き）も創業株主が57.4%を保つ。自社工場は組立だけで設備投資が小さく、評価額も上がるため、上場時に51%程度を保つ強気の資本政策にする判断。$m$, 'high', 'decided', 'confirmed',
  $m$[{"date": "2026-09-30", "source": "masa_direct", "note": "事業計画・資本政策の組み直しの指示（設立時に親族から1億円の出資と4億円の転換社債、上場時に過半数）"}, {"date": "2026-09-30", "source": "drive", "url": "https://drive.google.com/drive/folders/1H4spij995JOV3ArNYpYmww9QeH5PaU4H", "title": "成果物3 事業計画書（数値計画・資本政策表）"}]$m$::jsonb, 'masa_direct_20260930-1', 0.95, 'amie', 'amie', NOW(), 'pivot', 'project', false, 'internal'
WHERE NOT EXISTS (SELECT 1 FROM project_strategy_signals WHERE project_id = 'p20' AND source_hash = 'masa_direct_20260930-1');
