-- 12. 9月分の社内向け月報: 9/26の自動作成版に、9/26〜9/30の動き（9/28の3会議、9/29のコメント、9/30の判断と提出）を足す
--     社外向け（NIMSへ出した版）は提出記録として触らない。編集履歴はトリガーが actor=えいみ で残す
DO $mr$
DECLARE
  c text;
  olds text[] := ARRAY[$m$本契約は9月30日で履行期間が終わるため、納品物の整理と10月以降の契約の相談を開始した。$m$, $m$BUILD側からは、ビジネス側がマジョリティを持たない現体制では調達額が数億円から5億円前半で頭打ちになり得るという指摘を受け、経営体制と株式構成は継続論点として神谷さんとの間で協議を続けることとした。$m$, $m$9月28日には投資家面談を挟んだ定例を予定している。$m$, $m$利益相反書類は10月末提出、特許は設立前特定・設立後交渉の順とする。$m$, $m$JAFCOとの面談は9月28日に予定されていたが先方都合で日程を組み直す。$m$, $m$ライセンス対象特許の特定と、財務・事業計画の納品版資料の作成を進めている。$m$, $m$現体制のままでは調達額が頭打ちになるという指摘と、急な経営者交代は開発体制を壊すという制約の両立が最大の論点で、バトンパスの時期を誤ると調達と開発の両方を失う。$m$, $m$10月以降の契約の形を神谷さんと確定し、履行完了報告と納品物一式を仕上げる。利益相反マネジメント書類の10月末提出、財務シミュレーションの完成、神谷グループ全体の組織設計の書き出し、細線化線材のコイル化を進める。$m$, $m$9月25日 次期契約相談の打診連絡。$m$];
  news text[] := ARRAY[$m$本契約は9月30日で履行期間が終わるため、納品物の整理と10月以降の契約の相談を開始した。月末には、あきの10年計画を土台に事業計画と資本政策を組み直し、9月30日に履行完了報告書と成果物一式をNIMSへ提出した。$m$, $m$BUILD側からは、ビジネス側がマジョリティを持たない現体制では調達額が数億円から5億円前半で頭打ちになり得るという指摘を受けた。これに対しAMDは、こーじさんが代表を務め、そのこーじさんが過半数を持つことは妥当という見解をとる（9月26日 まさ）。$m$, $m$9月28日には社内定例、こーじさんとの1on1、現地定例を行った。社内定例では、2027年に1台を販売する前提で事業開発を先に始めること、NIMSの装置は初期の研究開発・PoC用途として説明できる可能性がある一方、NIMSの人件費を製品開発にそのまま使う前提にはしないことを確認した。現行の支援契約の終了後もAMDが支援を続けるには、秘密情報の扱いと対価を整理した契約の確認が要り、財源がない段階の対価は株式付与を案とした。現地定例では、ADR冷凍機を最初は無償か低額の保守で顧客の拠点に入れてデータを貯める方針の検討、コアのノウハウを公開しないこと、コア部品の組立は内製を基本とすることを話し、10月のポスター提出とマッチングイベントのピッチの準備に入った。

月末の事業計画と資本政策では、9月29日のあきのコメントを受けて、数値計画をあきの10年計画（2027〜2036年）に置き換え、商号の案を株式会社CryoX Technologies（仮称）にそろえた。9月30日にまさが、AMDの委託料（月60万円）を計画に入れること、NIMSの設備は初号機だけに使い（利益を見込まず、製品開発の人件費を製造原価に含める）、2028年から自社の組立工場で製造すること、設立直後に親族から株式1億円と転換社債4億円を受け、上場時も創業株主が過半数（計画57.4%）を保つ資本政策にすることを決めた。同日、履行完了報告書、成果物5点、9月分の月次進捗報告書、請求書をきよからNIMSへ送り、10月1日に検収と支払の手続きを進めるとの返信を受けた。$m$, $m$利益相反書類は10月末提出、特許は設立前特定・設立後交渉の順とする。こーじさんが代表で過半数を持つのが妥当というのがAMDの見解（9月26日）。会計ソフトはfreee会計、本店はこーじさんの持ち家の一部を借りる（了承済み）。NIMSの設備は初号機だけに使い、2028年から自社の組立工場で製造する。設立直後に親族から株式1億円と転換社債4億円を受け、VCは基本計画に入れず、上場時も創業株主が過半数を保つ（9月30日）。$m$, $m$JAFCOとの面談は9月28日に予定されていたが先方都合で日程を組み直す。常陽キャピタルパートナーズとAngel Bridgeは、10月8日にNIMS桜地区へ来訪する予定である。$m$, $m$ライセンス対象特許の特定を進めている。財務・事業計画の納品版資料は、成果物3（事業計画書と数値計画・資本政策表）として9月30日に提出した。$m$, $m$現体制のままではVCからの調達額が頭打ちになり得るという指摘に対し、設立時の資金は親族からの出資（株式1億円と転換社債4億円）で賄い、VCからの調達は基本計画に入れない方針とした。出資の条件（評価額、転換の条件と期限、未達時の返済）が12月までに固まらないと、設立時の資金計画が成り立たない。$m$, $m$10月以降の契約の形を神谷さんと確定する。設立時の出資者（親族）との条件（出資額・評価額・転換の条件・未達時の返済）の協議、商号の確定と商標の調査、利益相反マネジメント書類の10月末提出、DD資料の未作成分の作成、10月5〜6日のポスター提出、10月8日の投資会社2社の来訪、10月19日のピッチ、細線化線材のコイル化を進める。成果物3のExcelをNIMSへ送るかを決める。$m$, $m$9月25日 次期契約相談の打診連絡、9月28日 社内定例・こーじさん1on1・現地定例の記録、9月29日 あきのSlackコメント、9月30日 NIMSへの納品メールと10月1日の返信、成果物5（DD対応資料一覧・資金調達工程表）。$m$];
BEGIN
  SELECT final_content INTO c FROM monthly_reports WHERE project_id = 'p20' AND ym = '202609' FOR UPDATE;
  IF c IS NULL THEN RAISE EXCEPTION 'monthly report p20/202609 not found'; END IF;
  IF position($m$9月30日に履行完了報告書と成果物一式をNIMSへ提出した$m$ IN c) > 0 THEN RAISE NOTICE 'monthly report already updated'; RETURN; END IF;
  FOR i IN 1 .. array_length(olds, 1) LOOP
    IF length(c) - length(replace(c, olds[i], '')) <> length(olds[i]) THEN
      RAISE EXCEPTION 'monthly report anchor % not found exactly once', i;
    END IF;
    c := replace(c, olds[i], news[i]);
  END LOOP;
  PERFORM set_config('app.mrh_actor_kind', 'automation', true);
  PERFORM set_config('app.mrh_actor_label', 'えいみ（migration 463: 9月26日〜30日の動きを反映）', true);
  PERFORM set_config('app.mrh_source', 'migration:463', true);
  UPDATE monthly_reports SET final_content = c, draft_content = c WHERE project_id = 'p20' AND ym = '202609';
END $mr$;

-- 検証: 書いた件数がそろっていなければ全体を巻き戻す
DO $v$ BEGIN
  IF (SELECT count(*) FROM workspace_documents WHERE project_id = 'p20' AND folder_path = '月次報告書/2026年9月' AND entry_kind = 'link' AND source_ref LIKE 'drive_file:%') < 10 THEN RAISE EXCEPTION 'drive links missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM project_meeting_summaries WHERE meeting_id = $m$3db3u7cmq5gif30afqlegdd9ju_20260914T020000Z$m$) THEN RAISE EXCEPTION 'meeting card missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM project_company_profiles WHERE project_id = 'p20') THEN RAISE EXCEPTION 'company profile missing'; END IF;
  IF (SELECT count(*) FROM project_cost_items WHERE cost_model_id = 'cm_p20_260930') <> 10 THEN RAISE EXCEPTION 'cost items mismatch'; END IF;
  IF (SELECT count(*) FROM project_strategy_signals WHERE project_id = 'p20' AND source_hash IN ('nims_delivery_20260930', 'masa_direct_20260930-1', 'masa_direct_20260930-2', 'slack_20260929_aki_plan', 'slack_20260929_aki_name', 'masa_direct_20260926-1')) <> 6 THEN RAISE EXCEPTION 'signals mismatch'; END IF;
  IF EXISTS (SELECT 1 FROM project_knowledge WHERE id IN ('1eaeb766-f584-4449-b703-a8e413c5d9eb', '0d9c3f8e-fca3-4711-8110-43b6aa58f1a1', 'cfd1fcc4-5260-4d6d-9a06-4e46d74dfe54', 'eefbb5fb-2cc7-47c1-9558-f859aac01392', 'c0044243-de93-4cda-b7ac-ebfbbd20000b', '16713480-d004-41f8-ac4d-ad570ee61c53') AND status = 'active') THEN RAISE EXCEPTION 'knowledge not retired'; END IF;
  IF (SELECT count(DISTINCT entity_name) FROM project_knowledge WHERE project_id = 'p20' AND status = 'active' AND entity_name IN ($m$設立時の資金調達（親族出資）$m$, $m$資本政策の目標$m$, $m$製造方針（NIMSの設備と自社の組立工場）$m$, $m$事業計画（10年計画）$m$, $m$補助事業の想定$m$, $m$商号の案$m$, $m$経営体制に関するAMDの見解$m$, $m$会計ソフト$m$, $m$NIMS受託契約（W2026004905）の完了$m$, $m$あきの財務計画シートの注意点$m$)) <> 10 THEN RAISE EXCEPTION 'knowledge new mismatch'; END IF;
  IF (SELECT count(*) FROM project_questions WHERE id IN ('d4cb4031-8d6a-4c90-b663-e25674b4b797', 'c9ce6ca4-27a0-43ec-9671-f847d045733c', '885fbca3-86c6-4463-b118-d3d8db857ef5') AND status = 'answered') <> 3 THEN RAISE EXCEPTION 'answers mismatch'; END IF;
  IF (SELECT count(*) FROM project_actions WHERE id IN ('a0f0e856-f19c-519d-be2f-25139132a87c', '60086488-2678-5d95-89e0-32f0c69a9135', '39476590-08d5-564d-9428-4671140e6dec', 'e7f7420d-ed5f-58af-92e0-d3d765194e18', 'ccf06fdc-b65b-57a4-be2d-4ac48be021bc', '66a6bb3d-b368-572a-9fdb-e055743c8066', '5d0197f1-40a9-53fc-a20d-9e99bb46e578', 'f0d72327-586b-5095-ad97-f91fdf105514', 'c441c653-4fe3-529e-baef-731e10cc082a', '20967fe5-f215-5039-989c-085863a64177', '6db1429c-911b-5871-a2f1-f32f06a6f7d6', 'f9615fae-93b6-50e4-8a4d-dc18957881ed') AND review_state = 'proposed') <> 12 THEN RAISE EXCEPTION 'tasks mismatch'; END IF;
  IF (SELECT count(*) FROM project_management_partners WHERE project_id = 'p20' AND slug IN ('vc-build', 'vc-jafco', 'vc-joyo-capital-partners', 'vc-angel-bridge', 'jgc-global') AND deleted_at IS NULL) <> 5 THEN RAISE EXCEPTION 'partners mismatch'; END IF;
  IF position($m$9月30日に履行完了報告書と成果物一式をNIMSへ提出した$m$ IN (SELECT final_content FROM monthly_reports WHERE project_id = 'p20' AND ym = '202609')) = 0 THEN RAISE EXCEPTION 'monthly not updated'; END IF;
END $v$;

COMMIT;
